import React, { useEffect, useState } from 'react';
import styled from 'styled-components';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';


const HomePage = () => {
  const [lorries, setLorries] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    // Fetching lorries from backend
    axios.get('/api/lorries')
      .then(response => setLorries(response.data))
      .catch(error => console.error('Error fetching lorries:', error));
  }, []);

  const handleLorryClick = (registrationNumber) => {
    navigate(`/dashboard/${registrationNumber}`);
  };

  return (
    <Container>
      <Header>
        <CompanyName>Sri Murugan Rig Service</CompanyName>
        <OwnerInfo>
          <div>K Thangavelu</div>
          <div>9443769338</div>
        </OwnerInfo>
      </Header>

      <LorryCardContainer>
        {lorries.map(lorry => (
          <Card key={lorry.registration_number} onClick={() => handleLorryClick(lorry.registration_number)}>
            <CardTitle>{lorry.registration_number}</CardTitle>
          </Card>
        ))}
      </LorryCardContainer>
    </Container>
  );
};

export default HomePage;
